<script setup lang="ts">
import type {ChartSettings} from '../state/project';
defineProps<{settings:ChartSettings}>();const emit=defineEmits<{change:[value:Partial<ChartSettings>]}>();
function nullable(value:string){return value===''?null:Number(value);}
</script>
<template><section class="property-section axis-style-editor"><label>坐标轴文字</label><div class="axis-style-row"><strong>X 轴</strong><label>字号<input type="number" min="8" max="24" :value="settings.xAxisFontSize" @input="emit('change',{xAxisFontSize:Number(($event.target as HTMLInputElement).value)})"></label><label>颜色<input type="color" :value="settings.xAxisColor||'#687386'" @input="emit('change',{xAxisColor:($event.target as HTMLInputElement).value})"></label></div><div class="axis-style-row"><strong>左 Y 轴</strong><label>字号<input type="number" min="8" max="24" :value="settings.yAxisFontSize" @input="emit('change',{yAxisFontSize:Number(($event.target as HTMLInputElement).value)})"></label><label>颜色<input type="color" :value="settings.yAxisColor||'#687386'" @input="emit('change',{yAxisColor:($event.target as HTMLInputElement).value})"></label><label>小数<input type="number" min="0" max="6" :value="settings.yAxisDecimals??''" placeholder="自动" @input="emit('change',{yAxisDecimals:nullable(($event.target as HTMLInputElement).value)})"></label></div><div v-if="settings.type==='combo'" class="axis-style-row"><strong>右 Y 轴</strong><label>字号<input type="number" min="8" max="24" :value="settings.y2AxisFontSize" @input="emit('change',{y2AxisFontSize:Number(($event.target as HTMLInputElement).value)})"></label><label>颜色<input type="color" :value="settings.y2AxisColor||'#687386'" @input="emit('change',{y2AxisColor:($event.target as HTMLInputElement).value})"></label><label>小数<input type="number" min="0" max="6" :value="settings.y2AxisDecimals??''" placeholder="自动" @input="emit('change',{y2AxisDecimals:nullable(($event.target as HTMLInputElement).value)})"></label></div></section></template>
